"""sklearn.utils.validation — input validation helpers.

Implementations are pure-numpy and mirror the upstream behaviour where
behaviour is essential (shape checking, NaN detection, type coercion);
otherwise they're permissive no-ops that record state and pass through.
"""

import numpy as _np


def check_array(array, accept_sparse=False, *, accept_large_sparse=True,
                 dtype='numeric', order=None, copy=False, force_all_finite=True,
                 ensure_2d=True, allow_nd=False, ensure_min_samples=1,
                 ensure_min_features=1, estimator=None, input_name='',
                 ensure_non_negative=False):
    """Validate ``array`` and coerce it to a numpy array. Raises
    ``ValueError`` for shape/dtype/NaN violations, mirroring upstream."""
    out = _np.asarray(array)
    if dtype == 'numeric':
        if out.dtype.kind not in 'fiu':
            out = out.astype(float)
    elif dtype is not None and dtype != 'auto':
        try: out = out.astype(dtype)
        except Exception: pass
    if copy:
        out = out.copy()
    if ensure_2d:
        if out.ndim == 1:
            out = out.reshape(-1, 1)
        if out.ndim > 2 and not allow_nd:
            raise ValueError(f'{input_name or "array"} must be 2-D')
    if force_all_finite is True or (force_all_finite == 'allow-nan' and False):
        if out.dtype.kind == 'f' and not _np.all(_np.isfinite(out)):
            if force_all_finite is True:
                raise ValueError('Input contains NaN/inf')
    if ensure_min_samples > 0 and out.shape[0] < ensure_min_samples:
        raise ValueError(
            f'Found array with {out.shape[0]} sample(s); '
            f'minimum is {ensure_min_samples}')
    if out.ndim > 1 and ensure_min_features > 0 and out.shape[1] < ensure_min_features:
        raise ValueError(
            f'Found array with {out.shape[1]} feature(s); '
            f'minimum is {ensure_min_features}')
    if ensure_non_negative and _np.any(out < 0):
        raise ValueError('Negative values not allowed')
    return out


def check_X_y(X, y, accept_sparse=False, *, accept_large_sparse=True,
               dtype='numeric', order=None, copy=False, force_all_finite=True,
               ensure_2d=True, allow_nd=False, multi_output=False,
               ensure_min_samples=1, ensure_min_features=1, y_numeric=False,
               estimator=None):
    """Validate ``(X, y)`` together: same length, both coercible."""
    X = check_array(X, accept_sparse=accept_sparse, dtype=dtype, order=order,
                     copy=copy, force_all_finite=force_all_finite,
                     ensure_2d=ensure_2d, allow_nd=allow_nd,
                     ensure_min_samples=ensure_min_samples,
                     ensure_min_features=ensure_min_features,
                     estimator=estimator)
    y = _np.asarray(y)
    if y_numeric and y.dtype.kind not in 'fiu':
        y = y.astype(float)
    if len(X) != len(y):
        raise ValueError(f'X and y have inconsistent shapes: '
                          f'{X.shape} vs {y.shape}')
    return X, y


def check_consistent_length(*arrays):
    """Raise if any of ``arrays`` differs in length."""
    lengths = [len(a) for a in arrays if a is not None]
    if len(set(lengths)) > 1:
        raise ValueError(f'Inconsistent lengths: {lengths}')


def check_is_fitted(estimator, attributes=None, *, msg=None, all_or_any=all):
    """Raise NotFittedError if the estimator hasn't been fitted yet.
    Looks for any attribute ending in ``_`` that's not a class attribute."""
    from sklearn.exceptions import NotFittedError
    if attributes is None:
        attributes = [v for v in vars(estimator) if v.endswith('_')
                       and not v.startswith('__')]
        if not attributes:
            raise NotFittedError(
                msg or f'{type(estimator).__name__} not fitted yet — call fit() first')
        return
    check = all_or_any(hasattr(estimator, attr) for attr in attributes)
    if not check:
        raise NotFittedError(
            msg or f'{type(estimator).__name__} not fitted: missing {attributes}')


def check_random_state(seed):
    """Coerce ``seed`` to a :class:`numpy.random.RandomState` instance."""
    if seed is None or seed is _np.random:
        return _np.random.mtrand._rand
    if isinstance(seed, (int, _np.integer)):
        return _np.random.RandomState(seed)
    if isinstance(seed, _np.random.RandomState):
        return seed
    if isinstance(seed, _np.random.Generator):
        return seed
    raise ValueError(f'{seed!r} cannot be used as a random seed')


def column_or_1d(y, *, warn=False, dtype=None):
    """Ravel ``y`` to 1-D; raise if not vector-shaped."""
    y = _np.asarray(y)
    if dtype is not None:
        y = y.astype(dtype)
    if y.ndim == 2 and y.shape[1] == 1:
        return y.ravel()
    if y.ndim == 1:
        return y
    raise ValueError(f'y should be a 1-D array, got shape {y.shape}')


def has_fit_parameter(estimator, parameter):
    """True if ``estimator.fit`` accepts ``parameter``."""
    import inspect
    try:
        sig = inspect.signature(estimator.fit)
        return parameter in sig.parameters
    except Exception:
        return False


def indexable(*iterables):
    """Make sure each input is indexable; returns the same list."""
    return list(iterables)


def assert_all_finite(X, *, allow_nan=False, estimator_name=None, input_name=''):
    """Raise if X contains NaN or inf."""
    arr = _np.asarray(X)
    if arr.dtype.kind == 'f':
        if not _np.all(_np.isfinite(arr)):
            if allow_nan and _np.all(_np.isfinite(arr[~_np.isnan(arr)])):
                return
            raise ValueError(f'{input_name or "Input"} contains NaN or inf')


def check_scalar(x, name, target_type, *, min_val=None, max_val=None,
                  include_boundaries='both'):
    """Validate a scalar parameter's type + range."""
    if not isinstance(x, target_type):
        raise TypeError(f'{name} must be {target_type}, got {type(x)}')
    if min_val is not None:
        if include_boundaries in ('both', 'left') and x < min_val:
            raise ValueError(f'{name} >= {min_val}, got {x}')
        if include_boundaries in ('right', 'neither') and x <= min_val:
            raise ValueError(f'{name} > {min_val}, got {x}')
    if max_val is not None:
        if include_boundaries in ('both', 'right') and x > max_val:
            raise ValueError(f'{name} <= {max_val}, got {x}')
        if include_boundaries in ('left', 'neither') and x >= max_val:
            raise ValueError(f'{name} < {max_val}, got {x}')


def check_non_negative(X, whom):
    """Raise if X contains negative values."""
    if _np.any(_np.asarray(X) < 0):
        raise ValueError(f'Negative values in data passed to {whom}')


def check_symmetric(array, *, tol=1e-10, raise_warning=True, raise_exception=False):
    """Check if a 2-D array is symmetric to within ``tol``."""
    arr = _np.asarray(array)
    if arr.shape[0] != arr.shape[1]:
        if raise_exception:
            raise ValueError('Array must be square')
        return arr
    if not _np.allclose(arr, arr.T, atol=tol):
        if raise_exception:
            raise ValueError('Array is not symmetric')
        if raise_warning:
            import warnings
            warnings.warn('Array is not symmetric, symmetrizing')
        arr = 0.5 * (arr + arr.T)
    return arr


def validate_data(estimator, X='no_validation', y='no_validation', *,
                   reset=True, validate_separately=False, **check_params):
    """Validate input data — the modern (1.6+) entry point. The shim
    just delegates to :func:`check_array` / :func:`check_X_y`."""
    if isinstance(X, str) and X == 'no_validation' and isinstance(y, str):
        return None
    if isinstance(y, str) and y == 'no_validation':
        return check_array(X, **check_params)
    return check_X_y(X, y, **check_params)


def check_memory(memory):
    """Validate the ``memory`` parameter — accepts None, str path, or
    joblib.Memory-like object."""
    if memory is None or hasattr(memory, 'cache'):
        return memory
    if isinstance(memory, str):
        try:
            from joblib import Memory
            return Memory(memory, verbose=0)
        except Exception:
            pass
    return memory


